package assessment;

import java.util.*;
import static assessment.AssessmentServer.map;

/** Durable typed actions. All mutation paths run in the existing serialized store transaction. */
final class AgentUpdateRegistry {
    static final String TYPE="UPDATE_AGENT_V1";
    static final long WAIT_FOR_START_MILLIS=5*60*1000L;
    static final String BUSY_SQL="'WAITING','DOWNLOADING','INSTALLING','VERIFYING','UNCONFIRMED'";
    static final Set<String> BUSY=Set.of("WAITING","DOWNLOADING","INSTALLING","VERIFYING","UNCONFIRMED");
    static final Set<String> TERMINAL=Set.of("SUCCEEDED","FAILED","ROLLED_BACK","CANCELLED","EXPIRED");
    static final Set<String> DIAGNOSTICS=Set.of("OK","DOWNLOAD_FAILED","INVALID_SIGNATURE","INVALID_MANIFEST","HASH_MISMATCH","INCOMPATIBLE_ASSETS","VERSION_MISMATCH","DOWNGRADE_REFUSED","LOCAL_CHECK_FAILED","SERVICE_FAILED","PROBE_FAILED","ROLLED_BACK","RECOVERY_REQUIRED","NETWORK_UNCONFIRMED","UPDATE_FAILED","BATCH_STOPPED","AUTHORIZATION_REVOKED","TIMEOUT","CANCELLED","EXPIRED","MIGRATION_PROFILE_REQUIRED","UPDATE_PLAN_CHANGED","BRIDGE_NOT_CONFIRMED","MINIMUM_AGENT_VERSION","INVALID_OPERATION","ROUTE_CHANGED","INSUFFICIENT_DISK","LOCAL_INSTALL_FAILED","INVALID_BRIDGE","KNOWN_BRIDGE_REQUIRED","LEGACY_UPDATE_ACTIVE","INCOMPATIBLE_HELPER","BRIDGE_BASELINE_MISMATCH","MANAGER_PROBE_FAILED","IDENTITY_CHANGED","INVALID_BUNDLE","UNINSTALL_INVENTORY_REQUIRED","UPDATE_ALREADY_ACTIVE","AGENT_START_TIMEOUT");
    private final InventoryStore store;private final EnrollmentRegistry credentials;private final AgentUpdateCatalog catalog;private final AgentUpdateCoordinator coordinator;private final PostUpdateAssessments assessments;
    AgentUpdateRegistry(InventoryStore store,EnrollmentRegistry credentials,AgentUpdateCatalog catalog){this.store=store;this.credentials=credentials;this.catalog=catalog;this.coordinator=new AgentUpdateCoordinator(store,new AgentUpdateRoutes(catalog.rootFile()));this.assessments=new PostUpdateAssessments(store);}
    PostUpdateAssessments assessments(){return assessments;}
    private static String text(Object value){return value instanceof String?(String)value:"";}
    private static long number(Object value){return value instanceof Number?((Number)value).longValue():0;}
    private static void require(boolean condition,int status,String reason){if(!condition)throw new EnrollmentRegistry.Failure(status,reason);}
    static boolean busy(InventoryStore store,String host){return store.scalar("SELECT count(*) FROM agent_update_requests WHERE host_id=? AND status IN ("+BUSY_SQL+")",host)>0;}
    Map<String,Object> versionNotice(){
        long outdated=0;
        // Global, independent of inventory filters and pagination; no catalog verification or mutation.
        for(var group:store.rows("SELECT json_extract(h.payload,'$.collectorVersion') AS version,count(*) AS total FROM hosts h JOIN identities i ON i.id=h.id WHERE i.status='active' AND COALESCE(json_extract(h.payload,'$.agentLifecycle'),'')<>'uninstalled' GROUP BY json_extract(h.payload,'$.collectorVersion')")){
            String version=text(group.get("version"));
            if(AgentUpdateCatalog.version(version)&&AgentUpdateCatalog.compare(DashboardVersion.VERSION,version)>0)outdated+=number(group.get("total"));
        }
        return map("version",DashboardVersion.VERSION,"outdatedCount",outdated);
    }
    Map<String,Object> latest(String host){var records=store.documents("SELECT payload FROM agent_update_requests WHERE host_id=? AND coalesce(json_extract(payload,'$.parentOperationId'),'')='' ORDER BY rowid DESC LIMIT 1",host);return records.isEmpty()?null:records.get(0);}
    Map<String,Object> publicRecord(Map<String,Object> request){if(request==null)return null;Map<String,Object> safe=new LinkedHashMap<>();for(String key:List.of("id","hostId","batchId","targetVersion","fromVersion","status","createdAt","updatedAt","expiresAt","diagnostic","runAssessmentAfterUpdate","updateMode","migrationStage","startDeadlineAt"))safe.put(key,request.get(key));safe.put("assessment",assessments.publicRelation(text(request.get("id"))));return safe;}
    private void save(Map<String,Object> request){store.put("agent_update_requests",request);if(AgentUpdateCoordinator.managed(request))store.exec("UPDATE agent_update_operations SET status=?,payload=? WHERE id=?",request.get("status"),Json.stringify(request),request.get("id"));}
    private void status(Map<String,Object> request,String status,String diagnostic){
        List<Object> events=WorkRequests.updateEvents(request);boolean changed=!status.equals(request.get("status"))||!diagnostic.equals(request.get("diagnostic"));
        if(!request.containsKey("events"))request.put("historyPartial",true);
        String at=AssessmentServer.now();if(changed)events.add(map("at",at,"status",status,"diagnostic",diagnostic));
        if(events.size()>100){events=new ArrayList<>(events.subList(events.size()-100,events.size()));request.put("historyPartial",true);}
        request.put("events",events);request.put("status",status);request.put("diagnostic",diagnostic);request.put("updatedAt",at);request.put("updatedMillis",System.currentTimeMillis());
        if(TERMINAL.contains(status))request.put("finishedAt",at);save(request);
    }
    void maintain(){maintain(System.currentTimeMillis());}
    void maintain(long now){for(var request:store.documents("SELECT payload FROM agent_update_requests WHERE status IN ("+BUSY_SQL+") ORDER BY rowid")){
        String status=text(request.get("status"));if(status.equals("WAITING")){if(!"active".equals(credentials.credentialStatus(text(request.get("hostId")))))status(request,"CANCELLED","AUTHORIZATION_REVOKED");else if(number(request.get("expiresMillis"))<=now)status(request,"EXPIRED","EXPIRED");
            else if(!AgentUpdateCoordinator.child(request)&&next(request)&&number(request.get("claimedMillis"))==0){
                // Start this machine's clock only when its predecessors have finished.
                // Persist it so restarts and polling cannot renew the authorization.
                long deadline=number(request.get("startDeadlineMillis"));
                if(deadline==0){deadline=Math.min(now+WAIT_FOR_START_MILLIS,number(request.get("expiresMillis")));request.put("startDeadlineMillis",deadline);request.put("startDeadlineAt",java.time.Instant.ofEpochMilli(deadline).toString());save(request);}
                if(deadline<=now){status(request,"EXPIRED","AGENT_START_TIMEOUT");audit(request,"AGENT_UPDATE_START_TIMEOUT");}
            }
        }
        else if(!status.equals("UNCONFIRMED")&&(!"active".equals(credentials.credentialStatus(text(request.get("hostId"))))||now-number(request.get("updatedMillis"))>1800000L||now-number(request.get("claimedMillis"))>=86400000L))status(request,"UNCONFIRMED","TIMEOUT");
    }
        coordinator.maintain();assessments.maintain(now);
        for(var parent:store.documents("SELECT payload FROM agent_update_requests WHERE coalesce(json_extract(payload,'$.parentOperationId'),'')='' AND status IN ('SUCCEEDED','FAILED','ROLLED_BACK','CANCELLED','EXPIRED') AND (id IN (SELECT operation_id FROM agent_update_assessments WHERE state IN ('WAITING_FINAL','READY','QUEUED','RUNNING')) OR (json_type(payload,'$.updatePlan')='object' AND status IN ('FAILED','ROLLED_BACK') AND batch_id IN (SELECT batch_id FROM agent_update_requests WHERE status='WAITING')))")){
            if("SUCCEEDED".equals(parent.get("status")))assessments.onSucceeded(parent,now);else assessments.onStopped(parent,text(parent.get("diagnostic")),now);
            if(AgentUpdateCoordinator.managed(parent)&&Set.of("FAILED","ROLLED_BACK").contains(parent.get("status")))for(var sibling:store.documents("SELECT payload FROM agent_update_requests WHERE batch_id=? AND status='WAITING'",parent.get("batchId"))){status(sibling,"CANCELLED","BATCH_STOPPED");assessments.onStopped(sibling,"BATCH_STOPPED",now);}
        }
    }
    static int updaterGeneration(Object capability){return "update-v3".equals(capability)?3:"update-v2".equals(capability)?2:"update-v1".equals(capability)?1:0;}
    private String reason(Map<String,Object> host,int minUpdater){if(minUpdater<1)return "RELEASE_UNAVAILABLE";String id=text(host.get("id"));if(!"active".equals(credentials.credentialStatus(id))||"uninstalled".equals(host.get("agentLifecycle")))return "AGENT_REVOKED";var full=coordinator.current();if(full!=null){String routeReason=coordinator.reason(host,full);if(!routeReason.isEmpty())return routeReason;}else if(coordinator.configured()||updaterGeneration(host.get("updateCapability"))>=3)return "RELEASE_UNAVAILABLE";else if(updaterGeneration(host.get("updateCapability"))<minUpdater)return "CAPABILITY_REQUIRED";
        String version=text(host.get("collectorVersion"));if(!AgentUpdateCatalog.version(version))return "VERSION_UNKNOWN";if(AgentUpdateCatalog.compare(DashboardVersion.VERSION,version)<=0)return "NOT_NEWER";if(busy(store,id))return "UPDATE_BUSY";if(store.scalar("SELECT count(*) FROM jobs WHERE host_id=? AND status='RUNNING'",id)>0)return "JOB_RUNNING";if(store.scalar("SELECT count(*) FROM uninstall_requests WHERE host_id=? AND status IN ('WAITING','UNINSTALLING','UNCONFIRMED')",id)>0)return "UNINSTALL_BUSY";return "";}
    Map<String,Object> preview(String hostId,String environmentId){Map<String,Object> release=catalog.summary();var full=coordinator.current();if(full!=null)release=map("version",full.version(),"available",true,"reason","","minUpdater",3,"format","agent-bundle-v1");if(full==null&&coordinator.configured())release=map("version",DashboardVersion.VERSION,"available",false,"reason","RELEASE_UNAVAILABLE","minUpdater",3,"format","agent-bundle-v1");boolean available=Boolean.TRUE.equals(release.get("available"));List<Object> hosts=new ArrayList<>(),requests=new ArrayList<>();String where="1=1";List<Object> parameters=new ArrayList<>();
        if(!hostId.isEmpty()){require(store.get("hosts",hostId)!=null,404,"Host not found");where+=" AND id=?";parameters.add(hostId);}if(!environmentId.isEmpty()){String id=environmentId.equals("__unassigned__")?"":environmentId;require(id.isEmpty()||store.get("environments",id)!=null,404,"Environment not found");where+=" AND environment_id=?";parameters.add(id);}
        for(var host:store.documents("SELECT payload FROM hosts WHERE "+where+" ORDER BY hostname,id LIMIT 1001",parameters.toArray())){require(hosts.size()<1000,409,"Machine selection limit reached");String id=text(host.get("id")),reason=reason(host,available?(int)number(release.get("minUpdater")):0);var update=publicRecord(latest(id));hosts.add(map("id",id,"hostname",host.get("hostname"),"collectorVersion",host.get("collectorVersion"),"eligible",reason.isEmpty(),"reason",reason,"updateMode",full==null?"JAR":updaterGeneration(host.get("updateCapability"))>=3?"FULL":"MIGRATION","verificationPending",full!=null&&updaterGeneration(host.get("updateCapability"))<3,"update",update));if(update!=null)requests.add(update);}return map("release",release,"hosts",hosts,"requests",requests);}
    @SuppressWarnings("unchecked") Map<String,Object> create(Map<String,Object> input,UserAuth.User actor){
        require(Set.of("hostIds","targetVersion","requestKey","expiresInMinutes","runAssessmentAfterUpdate").containsAll(input.keySet()),400,"Unknown update field");require(input.get("hostIds") instanceof List<?> ids&&!ids.isEmpty()&&ids.size()<=1000,400,"Select 1 to 1000 machines explicitly");Object assessmentOption=input.getOrDefault("runAssessmentAfterUpdate",false);require(assessmentOption instanceof Boolean,400,"Assessment option must be boolean");boolean runAssessment=(Boolean)assessmentOption;List<Object> ids=(List<Object>)input.get("hostIds");List<String> selected=new ArrayList<>();for(Object value:ids){require(value instanceof String&&!text(value).isEmpty()&&text(value).length()<=100&&!selected.contains(value),400,"Invalid or duplicate host selection");selected.add(text(value));}List<String> normalized=new ArrayList<>(selected);Collections.sort(normalized);String selection=Json.stringify(normalized),version=text(input.get("targetVersion")),key=text(input.get("requestKey"));require(key.matches("[A-Za-z0-9_-]{16,100}"),400,"Invalid requestKey");
        var previous=store.rows("SELECT * FROM agent_update_batches WHERE request_key=?",key);if(!previous.isEmpty()){var batch=previous.get(0);require(selection.equals(batch.get("selection"))&&version.equals(batch.get("target_version")),409,"Request key belongs to another selection");var payload=(Map<String,Object>)Json.parse(text(batch.get("payload")));require(Boolean.TRUE.equals(payload.get("runAssessmentAfterUpdate"))==runAssessment,409,"Request key belongs to another assessment option");return batchResult(text(batch.get("id")),(List<Object>)payload.get("skipped"));}
        require(DashboardVersion.VERSION.equals(version),409,"TARGET_VERSION_CHANGED");var full=coordinator.current();require(full!=null||!coordinator.configured(),503,"RELEASE_UNAVAILABLE");var release=full==null?catalog.required(version):null;Object duration=input.getOrDefault("expiresInMinutes",60);require(duration instanceof Number&&((Number)duration).doubleValue()==number(duration)&&number(duration)>=5&&number(duration)<=1440,400,"Validity must be 5–1440 minutes");maintain();
        String batchId=UUID.randomUUID().toString(),createdAt=AssessmentServer.now();long expires=System.currentTimeMillis()+number(duration)*60000;List<Object> skipped=new ArrayList<>();int ordinal=0;
        for(String id:selected){var host=store.get("hosts",id);String reason=host==null?"HOST_NOT_FOUND":reason(host,full==null?release.minUpdater():3);Map<String,Object> snapshot=WorkRequests.snapshot(store,host,id);if(!reason.isEmpty()){snapshot.put("hostId",id);snapshot.put("reason",reason);skipped.add(snapshot);continue;}
            var request=map("id",UUID.randomUUID().toString(),"hostId",id,"batchId",batchId,"ordinal",ordinal++,"targetVersion",version,"fromVersion",host.get("collectorVersion"),"status","WAITING","createdAt",createdAt,"updatedAt",createdAt,"updatedMillis",System.currentTimeMillis(),"expiresMillis",expires,"expiresAt",java.time.Instant.ofEpochMilli(expires).toString(),"diagnostic","","actorId",actor.id(),"actorName",actor.name(),"historyPartial",false,"events",new ArrayList<>(List.of(map("at",createdAt,"status","WAITING","diagnostic",""))));request.putAll(snapshot);request.put("runAssessmentAfterUpdate",runAssessment);if(full!=null)coordinator.prepare(request,host,full);save(request);assessments.onCreated(request,System.currentTimeMillis());audit(request,"AGENT_UPDATE_REQUESTED");}
        store.exec("INSERT INTO agent_update_batches(id,request_key,target_version,selection,payload) VALUES(?,?,?,?,?)",batchId,key,version,selection,Json.stringify(map("createdAt",createdAt,"actorId",actor.id(),"actorName",actor.name(),"skipped",skipped,"runAssessmentAfterUpdate",runAssessment)));maintain();return batchResult(batchId,skipped);
    }
    private Map<String,Object> batchResult(String id,List<Object> skipped){List<Object> requests=new ArrayList<>();for(var request:store.documents("SELECT payload FROM agent_update_requests WHERE batch_id=? ORDER BY ordinal",id))requests.add(publicRecord(request));return map("batchId",id,"requests",requests,"skipped",skipped);}
    private Map<String,Object> own(String host,String id){var request=store.get("agent_update_requests",id);require(request!=null&&host.equals(request.get("hostId")),404,"Update request not found");return request;}
    private boolean next(Map<String,Object> request){return store.scalar("SELECT count(*) FROM agent_update_requests WHERE batch_id=? AND ordinal<? AND status IN ("+BUSY_SQL+")",request.get("batchId"),request.get("ordinal"))==0;}
    Map<String,Object> delivery(String host,String capability){maintain();var parents=store.documents("SELECT payload FROM agent_update_requests WHERE host_id=? AND coalesce(json_extract(payload,'$.parentOperationId'),'')='' AND status IN ("+BUSY_SQL+") ORDER BY rowid LIMIT 1",host);if(!parents.isEmpty()&&AgentUpdateCoordinator.managed(parents.get(0)))return coordinator.delivery(parents.get(0),capability);if(!busy(store,host))return null;var records=store.documents("SELECT payload FROM agent_update_requests WHERE host_id=? AND status IN ("+BUSY_SQL+") ORDER BY rowid LIMIT 1",host);var request=records.get(0);if(!"WAITING".equals(request.get("status"))||!next(request)||conflict(host))return map("blocked",true);try{if(updaterGeneration(capability)<catalog.required(text(request.get("targetVersion"))).minUpdater())return map("blocked",true);}catch(EnrollmentRegistry.Failure failure){return map("blocked",true);}return map("type",TYPE,"requestId",request.get("id"),"targetVersion",request.get("targetVersion"),"expiresMillis",request.get("expiresMillis"));}
    private boolean conflict(String host){return store.scalar("SELECT count(*) FROM jobs WHERE host_id=? AND status='RUNNING'",host)>0||store.scalar("SELECT count(*) FROM uninstall_requests WHERE host_id=? AND status IN ('WAITING','UNINSTALLING','UNCONFIRMED')",host)>0;}
    Map<String,Object> claim(String host,String id){maintain();var request=own(host,id);require(!AgentUpdateCoordinator.managed(request),409,"FULL_UPDATE_REQUIRED");String state=text(request.get("status"));if(Set.of("CANCELLED","EXPIRED").contains(state))return map("requestId",id,"executable",false);require(!TERMINAL.contains(state),409,"Update is already complete");require("active".equals(credentials.credentialStatus(host)),403,"Collector credential revoked");require(!conflict(host)&&next(request),409,"UPDATE_CONFLICT");var release=AgentUpdateCoordinator.child(request)?coordinator.legacyRelease(request):catalog.required(text(request.get("targetVersion")));
        if(state.equals("WAITING")){var machine=store.get("hosts",host);require(machine!=null&&updaterGeneration(machine.get("updateCapability"))>=release.minUpdater(),409,"CAPABILITY_REQUIRED");require(AgentUpdateCatalog.version(text(machine.get("collectorVersion")))&&AgentUpdateCatalog.compare(text(request.get("targetVersion")),text(machine.get("collectorVersion")))>0,409,"NOT_NEWER");long claimed=System.currentTimeMillis();request.put("claimedMillis",claimed);request.put("expiresMillis",claimed+86400000L);request.put("expiresAt",java.time.Instant.ofEpochMilli(claimed+86400000L).toString());status(request,"DOWNLOADING","");audit(request,"AGENT_UPDATE_CLAIMED");if(AgentUpdateCoordinator.child(request))coordinator.childChanged(request);}
        require(System.currentTimeMillis()-number(request.get("claimedMillis"))<86400000L,410,"Update authorization expired");
        return map("requestId",id,"executable",true,"targetVersion",request.get("targetVersion"),"expiresMillis",request.get("expiresMillis"));
    }
    AgentUpdateCatalog.Release download(String host,String id){var request=own(host,id);require(!AgentUpdateCoordinator.managed(request),409,"FULL_UPDATE_REQUIRED");require(Set.of("DOWNLOADING","INSTALLING","VERIFYING","UNCONFIRMED").contains(request.get("status"))&&number(request.get("claimedMillis"))>0,409,"Claim this update before downloading");require(System.currentTimeMillis()-number(request.get("claimedMillis"))<86400000L,410,"Update download authorization expired");require(!conflict(host)&&next(request),409,"UPDATE_CONFLICT");return AgentUpdateCoordinator.child(request)?coordinator.legacyRelease(request):catalog.required(text(request.get("targetVersion")));}
    void heartbeat(String host,String observedVersion){for(var request:store.documents("SELECT payload FROM agent_update_requests WHERE host_id=? AND status IN ('DOWNLOADING','INSTALLING','VERIFYING','UNCONFIRMED')",host)){if(number(request.get("claimedMillis"))>0&&observedVersion.equals(request.get("targetVersion"))){request.put("observedVersion",observedVersion);request.put("observedMillis",System.currentTimeMillis());save(request);}}}
    Map<String,Object> report(String host,Map<String,Object> input){require(Set.of("hostId","requestId","status","version","diagnostic").containsAll(input.keySet()),400,"Unknown update report field");var request=own(host,text(input.get("requestId")));require(!AgentUpdateCoordinator.managed(request),409,"FULL_UPDATE_REQUIRED");String state=text(input.get("status")),version=text(input.get("version")),diagnostic=text(input.get("diagnostic"));require(Set.of("DOWNLOADING","INSTALLING","VERIFYING","SUCCEEDED","FAILED","ROLLED_BACK","UNCONFIRMED").contains(state)&&DIAGNOSTICS.contains(diagnostic)&&AgentUpdateCatalog.version(version),400,"Invalid update report");String previous=text(request.get("status"));
        if(TERMINAL.contains(previous)){require(previous.equals(state)&&version.equals(request.get("reportedVersion"))&&diagnostic.equals(request.get("diagnostic")),409,"Conflicting terminal update report");return map("accepted",true,"requestId",request.get("id"),"status",previous);}
        require(!previous.equals("WAITING")&&number(request.get("claimedMillis"))>0,409,"Update must be claimed first");
        if(state.equals("SUCCEEDED")){require(diagnostic.equals("OK"),400,"Success requires an OK diagnostic");require(version.equals(request.get("targetVersion"))&&version.equals(request.get("observedVersion"))&&number(request.get("observedMillis"))>=number(request.get("claimedMillis"))&&version.equals(store.get("hosts",host).get("collectorVersion")),409,"Target version has not been observed after this claim");}
        else if(state.equals("ROLLED_BACK"))require(version.equals(request.get("fromVersion")),409,"Rollback version does not match the previous agent");
        else require(version.equals(request.get("fromVersion"))||version.equals(request.get("targetVersion")),409,"Reported version is outside this update");
        Map<String,Integer> order=Map.of("DOWNLOADING",1,"INSTALLING",2,"VERIFYING",3);if(order.containsKey(previous)&&order.containsKey(state))require(order.get(state)>=order.get(previous),409,"Update cannot move backwards");
        request.put("reportedVersion",version);status(request,state,diagnostic);audit(request,"AGENT_UPDATE_"+state);if(AgentUpdateCoordinator.child(request))coordinator.childChanged(request);else if(state.equals("SUCCEEDED"))assessments.onSucceeded(request,System.currentTimeMillis());else if(TERMINAL.contains(state))assessments.onStopped(request,diagnostic,System.currentTimeMillis());
        if(state.equals("FAILED")||state.equals("ROLLED_BACK"))for(var sibling:store.documents("SELECT payload FROM agent_update_requests WHERE batch_id=? AND status='WAITING'",request.get("batchId"))){status(sibling,"CANCELLED","BATCH_STOPPED");audit(sibling,"AGENT_UPDATE_BATCH_STOPPED");}
        return map("accepted",true,"requestId",request.get("id"),"status",state);
    }
    Map<String,Object> cancel(String host,String id,UserAuth.User actor){maintain();var request=own(host,id);require("WAITING".equals(request.get("status")),409,"Only a waiting update can be cancelled");status(request,"CANCELLED","CANCELLED");audit(request,"AGENT_UPDATE_CANCELLED",actor.id(),actor.name());return publicRecord(request);}
    Map<String,Object> bundleClaim(String host,String id){maintain();return coordinator.claim(own(host,id));}
    Map<String,Object> bundleReport(String host,Map<String,Object> input){var parent=own(host,text(input.get("operationId")));var ack=coordinator.report(parent,input);if("SUCCEEDED".equals(parent.get("status")))assessments.onSucceeded(parent,System.currentTimeMillis());else if(TERMINAL.contains(text(parent.get("status"))))assessments.onStopped(parent,text(parent.get("diagnostic")),System.currentTimeMillis());audit(parent,"AGENT_UPDATE_"+parent.get("status"));return ack;}
    byte[] bundleDownload(String host,String id,String part)throws java.io.IOException{return coordinator.download(own(host,id),part);}
    private void audit(Map<String,Object> request,String action){audit(request,action,text(request.get("actorId")),text(request.get("actorName")));}
    private void audit(Map<String,Object> request,String action,String actorId,String actorName){store.exec("INSERT INTO human_audit(at,actor_id,actor_name,action,target_id,target_name) VALUES(?,?,?,?,?,?)",AssessmentServer.now(),actorId,actorName,action,text(request.get("hostId")),text(request.get("targetVersion")));store.exec("DELETE FROM human_audit WHERE id NOT IN (SELECT id FROM human_audit ORDER BY id DESC LIMIT 10000)");}
}
